function scoreSentence(sent, lang) {
  // simple placeholder: use length and keyword hits
  const keywords = {
    en: ["great","love","best"],
    es: ["genial","me encanta","mejor"],
    fr: ["super","aimé","meilleur"]
  }[lang] || [];
